    (v_pack, 1, 1, 'multiple_choice', 'A classic margarita is built on which spirit?', '["Vodka","Rum","Tequila","Gin"]'::jsonb, '2'::jsonb, 'source: IBA official cocktail list — the margarita is tequila, triple sec, and lime juice.', 1, 30),
