    (v_pack, 1, 10, 'number_closest', 'How many gallons of beer are in a standard full US beer barrel?', null, '31'::jsonb, 'source: US Tax and Trade Bureau — a US beer barrel is defined as 31 gallons; a typical half-barrel keg holds 15.5.', 4, 35),
