    (v_pack, 2, 9, 'open_text', 'Which fortified wine takes its English name from Jerez, the Spanish city where it is made?', null, '{"accept":["sherry","jerez","sherry wine"]}'::jsonb, 'source: Consejo Regulador del Jerez — sherry is the anglicized name of Jerez de la Frontera''s fortified wine.', 3, 30),
