    (v_pack, 3, 4, 'multiple_choice', 'Arabica coffee is native to the highlands of which country?', '["Brazil","Colombia","Ethiopia","Indonesia"]'::jsonb, '2'::jsonb, 'source: Encyclopaedia Britannica — Coffea arabica is indigenous to the highlands of Ethiopia.', 3, 30),
    (v_pack, 3, 5, 'multiple_choice', 'Sriracha sauce is named after a seaside town in which country?', '["Vietnam","Thailand","China","Philippines"]'::jsonb, '1'::jsonb, 'source: Encyclopaedia Britannica — sriracha takes its name from Si Racha in Chonburi province, Thailand.', 3, 30),
