    (v_pack, 3, 8, 'multiple_choice', 'Traders from which country introduced the frying technique behind tempura to Japan in the 1500s?', '["Portugal","Spain","Netherlands","Britain"]'::jsonb, '0'::jsonb, 'source: Encyclopaedia Britannica — Portuguese traders and missionaries brought the batter-frying technique to Japan in the 16th century.', 3.5, 30),
