    (v_pack, 4, 1, 'multiple_choice', 'Pharmacist John Pemberton created Coca-Cola in 1886 in which US city?', '["Atlanta","Memphis","New Orleans","Chattanooga"]'::jsonb, '0'::jsonb, 'source: The Coca-Cola Company — Pemberton first sold the drink at an Atlanta pharmacy in 1886.', 2, 30),
