    (v_pack, 4, 3, 'open_text', 'Sweet, sour, salty, bitter — what is the 5th basic taste called?', null, '{"accept":["umami","savory","savoury"]}'::jsonb, 'source: Umami Information Center — Kikunae Ikeda identified umami as the 5th basic taste in 1908.', 2.5, 30),
