    (v_pack, 1, 1, 'multiple_choice', 'Guacamole is made primarily from which fruit?', '["Tomatillo","Avocado","Cucumber","Green apple"]'::jsonb, '1'::jsonb, 'source: Encyclopaedia Britannica — guacamole is a mashed-avocado dip; the name comes from Nahuatl ''ahuacamolli'', avocado sauce.', 1, 30),
