    (v_pack, 2, 3, 'multiple_choice', 'In Greek myth, who flew too close to the sun on wings of wax and feathers?', '["Daedalus","Hermes","Icarus","Apollo"]'::jsonb, '2'::jsonb, 'source: Ovid''s Metamorphoses — Icarus ignored his father Daedalus''s warning; the sun melted his wax wings and he fell into the sea.', 2.5, 30),
