    (v_pack, 1, 4, 'true_false', 'To drive from downtown Detroit into Windsor, Canada, you head south.', null, 'true'::jsonb, 'source: USGS maps — Windsor, Ontario sits due south of Detroit, across the Detroit River.', 2, 30),
