    (v_pack, 1, 6, 'multiple_choice', 'The Rock and Roll Hall of Fame opened in 1995 in which Great Lakes city?', '["Chicago","Detroit","Buffalo","Cleveland"]'::jsonb, '3'::jsonb, 'source: Rock & Roll Hall of Fame — the museum opened on Cleveland''s Lake Erie shore in September 1995.', 2, 30),
    (v_pack, 1, 7, 'multiple_choice', 'The 1987 film RoboCop patrols a dystopian future version of which city?', '["Chicago","Detroit","Los Angeles","New York"]'::jsonb, '1'::jsonb, 'source: Orion Pictures — RoboCop is set in a crime-ridden, near-future ''Old Detroit.''', 3, 30),
    (v_pack, 1, 8, 'multiple_choice', 'Which Detroit team won back-to-back 1989 and 1990 championships as the ''Bad Boys''?', '["Pistons","Red Wings","Tigers","Lions"]'::jsonb, '0'::jsonb, 'source: NBA — the ''Bad Boys'' Pistons took the 1989 and 1990 NBA Finals.', 2, 30),
