    (v_pack, 1, 10, 'multiple_choice', 'The University of Michigan was founded in 1817 — 20 years before statehood — in which city?', '["Ann Arbor","Detroit","Lansing","Monroe"]'::jsonb, '1'::jsonb, 'source: University of Michigan — founded 1817 in Detroit as the Catholepistemiad; it moved to Ann Arbor in 1837.', 4, 30),
    (v_pack, 2, 1, 'multiple_choice', 'Legendary investor Warren Buffett is ''the Oracle of'' which Midwest city?', '["Des Moines","Omaha","Kansas City","Minneapolis"]'::jsonb, '1'::jsonb, 'source: Berkshire Hathaway — Buffett has lived and invested from Omaha, Nebraska since the 1950s.', 2, 30),
    (v_pack, 2, 2, 'multiple_choice', 'Faygo''s iconic Redpop is what flavor?', '["Cherry","Fruit punch","Black cherry","Strawberry"]'::jsonb, '3'::jsonb, 'source: Faygo Beverages, Detroit since 1907 — Redpop is its famous strawberry soda.', 2, 30),
    (v_pack, 2, 3, 'number_closest', 'In what year did Ford''s Model T first go on sale?', null, '1908'::jsonb, 'source: Ford Motor Co. — the first Model T rolled out of Detroit''s Piquette Avenue plant in 1908.', 3, 35),
