    (v_pack, 2, 5, 'multiple_choice', 'Historic Route 66 began its 2,448-mile run to Santa Monica in which Midwest city?', '["Chicago","St. Louis","Detroit","Kansas City"]'::jsonb, '0'::jsonb, 'source: National Park Service Route 66 program — the Mother Road''s eastern terminus was Chicago.', 3, 30),
