    (v_pack, 2, 7, 'open_text', 'Minneapolis and St. Paul face each other across which river?', null, '{"accept":["Mississippi","Mississippi River","the Mississippi","the Mississippi River"]}'::jsonb, 'source: USGS — the Twin Cities grew up on opposite banks of the upper Mississippi River.', 3, 30),
    (v_pack, 2, 8, 'multiple_choice', 'Which state has stamped ''America''s Dairyland'' on its license plates since 1940?', '["Minnesota","Wisconsin","Iowa","Ohio"]'::jsonb, '1'::jsonb, 'source: Wisconsin DOT — the slogan joined Wisconsin plates in 1940 and never left.', 2, 30),
    (v_pack, 2, 9, 'multiple_choice', 'Motown legend Stevie Wonder was born in which Michigan city?', '["Saginaw","Flint","Detroit","Grand Rapids"]'::jsonb, '0'::jsonb, 'source: Britannica — Stevie Wonder was born in Saginaw in 1950; his family moved to Detroit when he was 4.', 3, 30),
    (v_pack, 2, 10, 'multiple_choice', 'The 1984 Tigers started the season 35-5, then won the World Series over which team?', '["Chicago Cubs","Los Angeles Dodgers","St. Louis Cardinals","San Diego Padres"]'::jsonb, '3'::jsonb, 'source: MLB — Detroit beat the San Diego Padres 4 games to 1; the Cubs had fallen to San Diego in the NLCS.', 4, 30),
    (v_pack, 3, 1, 'multiple_choice', 'FDR''s call for an ''Arsenal of Democracy'' became the WWII nickname of which US city?', '["Pittsburgh","Detroit","Chicago","Cleveland"]'::jsonb, '1'::jsonb, 'source: FDR''s December 1940 fireside chat — Detroit''s converted auto plants armed the Allies.', 3, 30),
