    (v_pack, 3, 3, 'multiple_choice', 'Immortalized in a 1976 Gordon Lightfoot ballad, the freighter Edmund Fitzgerald sank on which Great Lake?', '["Superior","Huron","Michigan","Erie"]'::jsonb, '0'::jsonb, 'source: NOAA — the Fitzgerald went down in a Lake Superior storm on November 10, 1975, with all 29 crew.', 3, 30),
