    (v_pack, 3, 5, 'open_text', 'In Cincinnati, a ''3-way'' is chili, shredded cheese, and what underneath?', null, '{"accept":["spaghetti","pasta","noodles","spaghetti noodles"]}'::jsonb, 'source: Cincinnati''s Empress chili parlors, since 1922 — a 3-way is spaghetti, chili, and a pile of cheddar.', 3, 30),
