    (v_pack, 4, 9, 'multiple_choice', 'In 1909, a stretch of Detroit''s Woodward Avenue became the nation''s first mile of what?', '["Painted center lines","Streetcar track","Concrete road","Electric streetlights"]'::jsonb, '2'::jsonb, 'source: FHWA and Michigan historical marker — Woodward between 6 and 7 Mile was paved as America''s first mile of concrete highway in 1909.', 5, 30),
    (v_pack, 4, 10, 'multiple_choice', 'After the near-bloodless 1835-36 ''Toledo War,'' Ohio kept Toledo and Michigan received what consolation prize?', '["Belle Isle","The western Upper Peninsula","The Lake Erie islands","$500,000 in gold"]'::jsonb, '1'::jsonb, 'source: Michigan History Center — Michigan gave up the Toledo Strip for the western Upper Peninsula (the east was already its territory) plus 1837 statehood. The copper and iron say Michigan won.', 4, 30),
